tools.example:
load carsmall
tbl = table(Weight, Horsepower, MPG);
mdl = fitlm(tbl, 'MPG ~ Weight + Horsepower + Weight:Horsepower');
disp(mdl)
fprintf('Adjusted R^2 = %.3f\n', mdl.Rsquared.Adjusted);
plotResiduals(mdl, 'probability')

load hospital
tbl = table(hospital.Age, double(hospital.Sex=='Female'), hospital.Smoker, ...
    'VariableNames', {'Age','Female','Smoker'});
mdl = fitglm(tbl, 'Smoker ~ Age + Female', 'Distribution', 'binomial');
disp(mdl.Coefficients)
prob = predict(mdl, table(45, 1, 'VariableNames', {'Age','Female'}));

rng(0)
x = linspace(0, 10, 60)';
y = 3.2*exp(-0.45*x) + 0.05*randn(size(x));
modelfun = @(b, x) b(1)*exp(-b(2)*x);
mdl = fitnlm(x, y, modelfun, [1 1]);
disp(mdl.Coefficients)
ci = coefCI(mdl);

load carsmall
tbl = table(Weight, Horsepower, Acceleration, Displacement, MPG);
mdl = stepwiselm(tbl, 'constant', 'Upper', 'interactions', ...
    'Criterion', 'bic', 'Verbose', 1);
disp(mdl.Formula)

load ionosphere
tbl = array2table(X(:,1:8));
tbl.y = double(strcmp(Y, 'g'));
mdl = stepwiseglm(tbl, 'constant', 'Upper', 'linear', ...
    'Distribution', 'binomial', 'Criterion', 'aic');
disp(mdl)

load flu
flu2 = stack(flu, 2:10, 'NewDataVariableName', 'FluRate', ...
    'IndexVariableName', 'Region');
flu2.Date = double(flu2.Date);
lme = fitlme(flu2, 'FluRate ~ 1 + WtdILI + (1 | Region)');
disp(lme)
[beta, names] = fixedEffects(lme);

load carsmall
keep = ~isnan(MPG) & ~isnan(Weight) & ~isnan(Horsepower);
X = [ones(sum(keep),1) Weight(keep) Horsepower(keep)];
y = MPG(keep);
[b, bint, r, rint, stats] = regress(y, X);
fprintf('R^2 = %.3f, p = %.3g\n', stats(1), stats(3));

rng(0)
x = (1:50)';
y = 2*x + 5 + randn(50,1);
y([10 30]) = y([10 30]) + 60;      % outliers
bLS = [ones(50,1) x] \ y;
[bR, stats] = robustfit(x, y);
plot(x, y, 'o', x, [ones(50,1) x]*bLS, '--', x, bR(1)+bR(2)*x, '-')

rng(1)
x = linspace(0, 5, 40)';
y = 10 ./ (1 + exp(-2*(x-2.5))) + 0.3*randn(40,1);
modelfun = @(b, x) b(1) ./ (1 + exp(-b(2)*(x - b(3))));
[beta, R, J, CovB] = nlinfit(x, y, modelfun, [8 1 2]);
ci = nlparci(beta, R, 'covar', CovB);

modelfun = @(b, x) b(1)*exp(-b(2)*x);
x = (0:0.5:10)';
y = 5*exp(-0.3*x) + 0.05*randn(size(x));
[beta, R, J] = nlinfit(x, y, modelfun, [4 0.5]);
ci = nlparci(beta, R, 'jacobian', J, 'alpha', 0.01)

modelfun = @(b, x) b(1)*exp(-b(2)*x);
x = (0:0.5:10)'; y = 5*exp(-0.3*x) + 0.05*randn(size(x));
[beta, R, J] = nlinfit(x, y, modelfun, [4 0.5]);
xg = linspace(0, 10, 200)';
[yp, d] = nlpredci(modelfun, xg, beta, R, 'Jacobian', J);
plot(x, y, 'o', xg, yp, '-', xg, yp+d, ':', xg, yp-d, ':')

load acetylene
X = [x1 x2 x3];
[B, FitInfo] = lasso(X, y, 'CV', 10, 'Alpha', 0.75);
lassoPlot(B, FitInfo, 'PlotType', 'CV'); legend('show')
idx = FitInfo.Index1SE;
coefs = [FitInfo.Intercept(idx); B(:, idx)]

load acetylene
X = [x1 x2 x3];
k = 0:1e-3:5e-2;
B = ridge(y, X, k, 0);
plot(k, B(2:end,:)', 'LineWidth', 1.5)
xlabel('Ridge parameter'), ylabel('Coefficient')

load spectra
[XL, YL, XS, YS, beta, pctvar, mse] = plsregress(NIR, octane, 10, 'CV', 10);
plot(0:10, mse(2,:), '-o'); xlabel('Components'); ylabel('CV MSE')
yfit = [ones(size(NIR,1),1) NIR] * beta;

load flu
Y = double(flu{:, 2:4});
n = size(Y, 1);
X = [ones(n,1) (1:n)'];
[beta, Sigma, E, CovB, logL] = mvregress(X, Y);
disp(beta)

load fisheriris
sp = categorical(species);
[B, dev, stats] = mnrfit(meas, sp);
probs = mnrval(B, meas(1:5, :));
disp(probs)

rng(0)
X = sprandn(20000, 5000, 0.001);
beta = zeros(5000,1); beta(1:20) = randn(20,1);
y = X*beta + 0.1*randn(20000,1);
Mdl = fitrlinear(X, y, 'Learner', 'leastsquares', ...
    'Regularization', 'lasso', 'Lambda', 1e-4);
yhat = predict(Mdl, X(1:5,:));

load carsmall
keep = ~any(isnan([Weight Horsepower MPG]), 2);
X = [Weight(keep) Horsepower(keep)];
y = MPG(keep);
Mdl = fitrsvm(X, y, 'KernelFunction', 'gaussian', ...
    'KernelScale', 'auto', 'Standardize', true);
fprintf('Resub loss: %.2f\n', resubLoss(Mdl));

load carsmall
tbl = table(Weight, Horsepower, Acceleration, MPG);
tree = fitrtree(tbl, 'MPG', 'MinLeafSize', 8, 'Surrogate', 'on');
view(tree, 'Mode', 'graph')
imp = predictorImportance(tree);
cvtree = crossval(tree, 'KFold', 10);
fprintf('CV MSE = %.2f\n', kfoldLoss(cvtree));

load carsmall
X = [Weight Horsepower Acceleration Displacement];
y = MPG;
t = templateTree('MaxNumSplits', 20, 'Surrogate', 'on');
Mdl = fitrensemble(X, y, 'Method', 'LSBoost', ...
    'NumLearningCycles', 300, 'LearnRate', 0.1, 'Learners', t);
L = loss(Mdl, X, y);
plot(loss(Mdl, X, y, 'mode', 'cumulative'))

rng(0)
x = linspace(0, 10, 25)';
y = sin(x) + 0.1*randn(size(x));
gpr = fitrgp(x, y, 'KernelFunction', 'matern52', 'Standardize', true);
xg = linspace(-1, 11, 300)';
[ypred, ysd, yci] = predict(gpr, xg);
plot(x, y, 'o', xg, ypred, '-'); hold on
fill([xg; flipud(xg)], [yci(:,1); flipud(yci(:,2))], 'b', 'FaceAlpha', 0.1)

load carsmall
tbl = table(Weight, Horsepower, Model_Year, MPG);
tbl.Model_Year = categorical(tbl.Model_Year);
mdl = fitlm(tbl, 'MPG ~ Weight + Horsepower + Model_Year');
disp(anova(mdl))
disp(anova(mdl, 'summary'))

load carsmall
mdl = fitlm([Weight Horsepower], MPG);
ci95 = coefCI(mdl);
ci99 = coefCI(mdl, 0.01);
disp(table(mdl.Coefficients.Estimate, ci95(:,1), ci95(:,2), ...
    'VariableNames', {'Est','Lower','Upper'}))

load carsmall
tbl = table(Weight, Horsepower, MPG);
mdl = fitlm(tbl, 'MPG ~ Weight + Horsepower');
new = table([2500; 3500], [110; 160], 'VariableNames', {'Weight','Horsepower'});
[yp, yci] = predict(mdl, new, 'Prediction', 'observation');
disp([yp yci])

rng(0)
x = linspace(0, 10, 30)';
y = 0.5*x.^2 - 2*x + 3 + randn(30,1);
[p, S] = polyfit(x, y, 2);
xg = linspace(0, 10, 200)';
[yg, d] = polyconf(p, xg, S, 'predopt', 'curve');
plot(x, y, 'o', xg, yg, '-', xg, yg+d, ':', xg, yg-d, ':')
